CREATE TABLE clicks (
    id INT PRIMARY KEY,
    timestamp TIMESTAMP,
    user_id INT,
    event_type STRING,
    value INT
) WITH (
    'connector' = 'kafka',
    'topic' = 'clicks',
    'properties.bootstrap.servers' = 'localhost:9092',
    'properties.group.id' = 'clicks-group',
    'properties.key.deserializer' = 'org.apache.kafka.common.serialization.StringDeserializer',
    'properties.value.deserializer' = 'org.apache.kafka.common.serialization.StringDeserializer'
);

-- SQL block to create the enriched table for clicks
CREATE TABLE clicks_enriched (
    id INT PRIMARY KEY,
    timestamp TIMESTAMP,
    user_id INT,
    event_type STRING,
    value INT,
    enriched_data STRING
) WITH (
    'connector' = 'kafka',
    'topic' = 'clicks-enriched',
    'properties.bootstrap.servers' = 'localhost:9092',
    'properties.group.id' = 'clicks-enriched-group',
    'properties.key.deserializer' = 'org.apache.kafka.common.serialization.StringDeserializer',
    'properties.value.deserializer' = 'org.apache.kafka.common.serialization.StringDeserializer'
);

